{
  "_ulid": "01KJ3FXGTS351B70HBQ44Y744S",
  "slugs": [
    "interactive-triage-ui"
  ],
  "title": "Interactive Triage UI",
  "type": "requirement",
  "status": {
    "maturity": "draft",
    "implementation": "implemented"
  },
  "tags": [],
  "description": "Card-based interactive triage mode in the web dashboard.\nOne-at-a-time item presentation with action selection,\nreasoning input, and real-time updates.\n",
  "acceptance_criteria": [
    {
      "id": "ac-1",
      "given": "the user navigates to the triage page\n",
      "when": "untriaged inbox items exist\n",
      "then": "displays a card-based view showing item text, tags, age, and added_by\n"
    },
    {
      "id": "ac-2",
      "given": "the user views a triage card for an item with an existing agent triage record\n",
      "when": "the record has status triaged\n",
      "then": "shows the agent recommended action, reasoning, and evidence refs\n"
    },
    {
      "id": "ac-3",
      "given": "the user selects an action and enters reasoning\n",
      "when": "they submit the decision\n",
      "then": "creates or updates a triage record via the API and advances to next item\n"
    },
    {
      "id": "ac-4",
      "given": "the user disagrees with the agent recommendation\n",
      "when": "they select a different action with override reasoning\n",
      "then": "the triage record captures the override with user attribution\n"
    },
    {
      "id": "ac-5",
      "given": "the user is in triage mode\n",
      "when": "they use next/previous navigation\n",
      "then": "they can browse items without committing decisions, and\nalready-triaged items show their decision state\n"
    },
    {
      "id": "ac-6",
      "given": "the triage page is open\n",
      "when": "another client creates or updates a triage record\n",
      "then": "the view updates in real-time via WebSocket triage:updates topic\n"
    },
    {
      "id": "ac-7",
      "given": "the user wants to filter items\n",
      "when": "they use tag or status filters\n",
      "then": "the card view shows only matching items with updated progress count\n"
    },
    {
      "id": "ac-8",
      "given": "the web UI is in static mode\n",
      "when": "the user navigates to triage\n",
      "then": "triage decisions display read-only with action buttons hidden,\ncard navigation still works for browsing\n"
    }
  ],
  "depends_on": [],
  "implements": [],
  "relates_to": [],
  "tests": [],
  "traits": [
    "@trait-websocket-protocol"
  ],
  "created": "2026-02-22T20:16:09.049Z",
  "notes": [],
  "_sourceFile": "/home/chapel/Projects/kynetic-spec-ui/.kspec/modules/cli.yaml",
  "_path": "features[28].requirements[3]",
  "inherited_traits": [
    {
      "ref": "@trait-websocket-protocol",
      "title": "WebSocket Protocol Patterns",
      "acceptance_criteria": [
        {
          "id": "ac-1",
          "given": "WebSocket connection is established",
          "when": "client connects",
          "then": "server assigns unique connection ID and sends connected event with session_id"
        },
        {
          "id": "ac-2",
          "given": "client wants notifications",
          "when": "subscribe command sent with topics array",
          "then": "server tracks subscription and sends ack with request_id"
        },
        {
          "id": "ac-3",
          "given": "client is subscribed to topic",
          "when": "relevant change occurs",
          "then": "server broadcasts event with format {msg_id, seq, timestamp, topic, event, data}"
        },
        {
          "id": "ac-4",
          "given": "WebSocket connection is active",
          "when": "30 seconds pass without activity",
          "then": "server sends ping frame"
        },
        {
          "id": "ac-5",
          "given": "ping was sent",
          "when": "no pong received within 90 seconds",
          "then": "connection is closed with code 1001"
        },
        {
          "id": "ac-6",
          "given": "server sends events",
          "when": "client cannot keep up (backpressure)",
          "then": "server pauses non-critical broadcasts until drain event"
        },
        {
          "id": "ac-7",
          "given": "connection is closing",
          "when": "close initiated",
          "then": "use code 1000 for clean close, 1001 for timeout, 1011 for error"
        },
        {
          "id": "ac-8",
          "given": "client reconnects after disconnect",
          "when": "new connection established",
          "then": "client resets sequence tracking (lastSeqProcessed = -1) since server generates new sequence"
        }
      ]
    }
  ]
}
